var e=`#38bdf8`,t=`#f472b6`,n=`#fde047`,r=`#4ade80`,i=(e,t={})=>({bg:e,round:!0,...t}),a=(e,t=``,n=`#0b1020`)=>({bg:e,text:t,color:n}),o=(e=``)=>({ring:n,text:e,color:n}),s={b:i(e),p:i(t),B:i(e,{ring:n}),P:i(t,{ring:n}),x:o(`×`),o:o()},c=(e=`#e2e8f0`)=>Object.fromEntries(`0123456789`.split(``).map(t=>[t,{text:t,color:e}])),l=`#fca5a5`,u=`#86efac`,d=`#a5b4fc`,f=`#fde047`,p=e=>({bg:e,text:`👑`}),m=e=>({bg:e,text:`✕`,color:`#1f293799`}),h=(e,t)=>({bg:`#2e2866`,text:e,color:e.startsWith(`-`)?`#fb7185`:`#f1f5f9`,...t?{ring:t}:{}}),g={...Object.fromEntries(`123456789`.split(``).map(e=>[e,h(e)])),...Object.fromEntries(`123456789`.split(``).map((t,n)=>[String.fromCharCode(97+n),h(t,e)])),...Object.fromEntries(`123456789`.split(``).map((e,n)=>[String.fromCharCode(65+n),h(e,t)])),m:h(`-3`),n:h(`-2`),x:h(`-2`,t),S:{bg:`#ffd23f`,round:!0,text:`✚`,color:`#7c5a00`}},_=`#ff3b5c`,v={L:{text:`▶`,color:_},"-":{bg:`#3b0d18`,text:`─`,color:_},"|":{bg:`#3b0d18`,text:`│`,color:_},"/":{bg:`#2a3358`,text:`╱`,color:`#e2e8f0`},"\\":{bg:`#2a3358`,text:`╲`,color:`#e2e8f0`},s:{bg:`#3b0d18`,text:`╱`,color:`#c4b5fd`,ring:`#a78bfa`},C:{bg:`#1c1a42`,text:`◆`,color:`#0e7490`},c:{bg:`#3b0d18`,text:`◆`,color:`#a5f3fc`,ring:`#67e8f9`},B:{bg:`#1c1a42`,text:`●`,color:`#0f0f17`,ring:`#52525b`},b:{bg:`#7f1d1d`,text:`✹`,color:`#fde047`,ring:`#f97316`}},y=(e,t)=>({bg:`#1e1b4b`,text:e,color:`#e2e8f0`,round:!0,...t?{ring:t}:{}}),b={a:y(`1`),A:y(`1`,n),b:y(`2`),1:a(`#5eead4`,`1`),2:a(`#818cf8`,`2`),3:a(`#a78bfa`,`3`)},x=e=>({text:e,color:`#f8fafc`}),S={zeltlager:{goal:`Stell neben jeden Baum genau ein Zelt – so, dass alle Zahlen am Rand stimmen.`,steps:[`Jeder Baum bekommt genau ein Zelt direkt daneben: links, rechts, oben oder unten – nicht schräg.`,`Zelte berühren sich nie, auch nicht über Eck.`,`Die Zahlen am Rand sagen, wie viele Zelte in dieser Zeile bzw. Spalte stehen. Grün = stimmt, rot = zu viele oder nicht mehr zu schaffen.`,`Antippen schaltet weiter: leer → Gras → Zelt → leer. Gras ist nur eine Merkhilfe für „hier sicher kein Zelt“. Wischen über leere Felder malt Gras.`,`„Rasen“ füllt alle Felder mit Gras, auf denen sicher kein Zelt stehen kann. Sterne gibt es für schnelles Lösen.`],tips:[`Beginne bei den Nullen: In diesen Zeilen und Spalten ist alles Gras.`,`Ein Baum, neben dem nur noch ein freies Feld ist, verrät dir sofort sein Zelt.`,`Rund um jedes Zelt ist alles Gras – das macht oft die Nachbarbäume eindeutig.`],example:{title:`Ein kleiner Zeltplatz (4 × 4)`,legend:{0:x(`0`),1:x(`1`),2:x(`2`),T:{bg:`#3f7a3a`,text:`🌳`},Z:{bg:`#55924c`,text:`⛺`},N:{bg:`#55924c`,text:`⛺`,ring:n},g:{bg:`#21532b`,text:`·`,color:`#bbf7d0`},".":{bg:`#55924c`}},frames:[{grid:[` 1101`,`1.T..`,`1....`,`0...T`,`1T...`],note:`Zeile 3 hat eine 0: Dort steht kein Zelt. Der Baum unten links hat deshalb nur noch rechts Platz.`},{grid:[` 1101`,`1.T..`,`1....`,`0gggT`,`1TNgg`],note:`Zelt neben den Baum – die Zeile hat jetzt ihr eines Zelt, der Rest wird Gras.`},{grid:[` 1101`,`1ZTgg`,`1gggZ`,`0gggT`,`1TZgg`],note:`Spalte 3 hat eine 0, also kommt das Zelt des rechten Baums nach oben. Der Rest folgt – fertig!`}]}},revierkampf:{goal:`Nimm deinem Gegner den Platz: Wer nicht mehr ziehen kann, verliert.`,steps:[`Ein Zug hat zwei Teile. Zuerst zieht eine deiner Wächterinnen wie eine Dame im Schach: gerade oder schräg, so weit sie will – aber nicht über Felsen oder andere Figuren.`,`Danach wirft dieselbe Wächterin von ihrem neuen Feld aus einen Felsen – wieder wie eine Dame – auf ein freies Feld. Auch das Feld, von dem sie gekommen ist, geht.`,`Felsen bleiben für immer liegen. Das Brett wird so immer enger.`,`Kann einer nicht mehr ziehen, hat er verloren.`,`Sind die Reviere ganz getrennt (kein freies Gebiet berührt beide Farben), wird gezählt: Wer mehr freie Felder in seinen Revieren hat, gewinnt. Gleichstand gewinnt, wer zuletzt gezogen hat.`],tips:[`„Reviere“ färbt jedes freie Feld in der Farbe dessen, der es schneller erreicht – ein guter Kompass.`,`Bleib in der Mitte beweglich. Eine Wächterin in der Ecke wird schnell eingemauert.`,`Mit dem Felsen kannst du dem Gegner den Weg abschneiden – oft wertvoller als der Zug selbst.`],example:{title:`Ziehen und werfen`,legend:{".":{bg:`#e7d6b0`},B:{bg:e,round:!0,text:`♜`,color:`#0c4a6e`},b:{bg:e,round:!0,text:`♜`,color:`#0c4a6e`,ring:n},P:{bg:t,round:!0,text:`♜`,color:`#831843`},"#":{bg:`#78716c`,text:`▲`,color:`#d6d3d1`},X:{bg:`#a8a29e`,text:`▲`,color:`#f5f5f4`,ring:n}},frames:[{grid:[`P....`,`.....`,`..#..`,`.....`,`B....`],note:`Blau ist dran. Die Wächterin unten links zieht wie eine Dame.`},{grid:[`P....`,`.....`,`b.#..`,`.....`,`.....`],note:`Sie zieht zwei Felder nach oben.`},{grid:[`P.X..`,`.....`,`B.#..`,`.....`,`.....`],note:`Dann wirft sie einen Felsen schräg nach oben. Pink hat nun weniger Platz zum Ziehen.`}]}},ballonfahrt:{goal:`Fahr mit dem Heißluftballon so weit wie möglich – bevor dich das Gewitter einholt.`,steps:[`Finger halten = der Brenner heizt, der Ballon steigt. Loslassen = die Luft kühlt ab, er sinkt. Der Ballon reagiert träge – wie ein echter.`,`Vorwärts bringt dich nur der Wind. In jeder Höhe weht er anders schnell: Die Pfeile rechts zeigen es (gelb = schnell, grau = langsam).`,`Von links jagt ein Gewitter, das immer schneller wird. Oben steht, wie weit es noch hinter dir ist.`,`Gewitterwolken, Vögel, Berge und der Boden kosten einen Sandsack. Sind alle weg, ist die Fahrt vorbei.`,`Sterne bringen Punkte, Gasflaschen füllen den Brenner. Jeder Meter zählt einen Punkt.`],tips:[`Heiz früh und kurz statt spät und lange – sonst schießt du über die Zielhöhe hinaus.`,`In jedem Abschnitt bleibt mindestens eine Höhe frei von Gefahren.`,`Langsame Schichten sind sicher, aber das Gewitter holt auf. Wag dich rechtzeitig in den schnellen Wind.`]},skyline:{goal:`Bau eine Stadt aus Hochhäusern: In jeder Zeile und jeder Spalte steht jede Höhe genau einmal – und die Zahlen am Rand stimmen.`,steps:[`Tippe ein Feld an und dann unten eine Höhe. Die Höhe 1 ist das kleinste Haus, die größte Zahl das höchste.`,`Eine Randzahl sagt, wie viele Häuser man von dort aus in dieser Zeile oder Spalte sieht. Ein höheres Haus verdeckt alle kleineren dahinter.`,`Randzahl 1 = das höchste Haus steht direkt am Rand. Randzahl so groß wie das Feld = die Häuser stehen der Größe nach (1, 2, 3 …).`,`Grün: Diese Randzahl stimmt. Rot: Hier passt etwas nicht (doppelte Höhe oder zu viele/zu wenige Häuser zu sehen).`,`„Notizen“ schaltet auf kleine Merkzahlen um. Sterne gibt es für schnelles Bauen; ein Tipp setzt ein richtiges Haus fest.`],tips:[`Beginne bei den Randzahlen 1 und der größten Zahl – dort weißt du sofort etwas.`,`Neben einer großen Randzahl stehen vorn kleine Häuser, neben einer kleinen Randzahl steht das höchste Haus weit vorn.`,`Zwei Randzahlen derselben Zeile zusammen verraten oft, wo das höchste Haus stehen muss.`],example:{title:`Eine kleine Stadt (3 × 3)`,legend:b,frames:[{grid:[` bab`,`b...`,`a...`,`b...`],note:`Oben in Spalte 2 steht eine 1: Von dort sieht man nur ein Haus. Also steht das höchste (3) ganz oben in dieser Spalte.`},{grid:[` bab`,`b.3.`,`A3..`,`b...`],note:`Links in Zeile 2 steht auch eine 1 – dort steht die 3 ganz vorn.`},{grid:[` bab`,`b132`,`a321`,`b213`],note:`Der Rest folgt: jede Höhe einmal je Zeile und Spalte. Alle Randzahlen stimmen – die Stadt steht!`}]}},sternbilder:{goal:`Schließe mehr Dreiecke als dein Gegner. Ihr zieht abwechselnd Linien zwischen den Sternen.`,steps:[`Tippe einen Stern an (oder wisch von ihm los) und dann einen zweiten: Die beiden werden mit einer Linie verbunden. Gelb gestrichelt siehst du, wohin du ziehen darfst.`,`Linien dürfen sich nie kreuzen und nicht durch einen anderen Stern laufen.`,`Schließt deine Linie ein Dreieck, in dem kein Stern liegt, gehört es dir – und du bist nochmal dran.`,`Ein Dreieck zählt 1 Punkt, für jeden goldenen Stern an seinen Ecken einen mehr (bis zu 4).`,`Geht keine Linie mehr, ist der Himmel voll. Wer mehr Punkte hat, gewinnt.`],tips:[`Zieh keine Linie, die ein Dreieck bis auf eine Seite fertig macht – die letzte Seite holt sich sonst der Gegner.`,`Gegen Ende muss irgendwer etwas verschenken. Dann verschenk die kleinste Kette – und hol dir danach die große.`,`Dreiecke an goldenen Sternen sind doppelt so viel wert: Schau, wer sie zuerst schließen kann.`]},echolot:{goal:`Tauch mit deinem U-Boot so tief wie möglich durch eine dunkle Höhle – ohne gegen Wände oder Minen zu stoßen.`,steps:[`Jede Berührung des Bildschirms schickt einen Sonar-Ping. Der Ring breitet sich aus: Wände, Minen und Perlen, die er streift, leuchten kurz auf.`,`Halte den Finger auf dem Bildschirm und zieh nach links oder rechts – das U-Boot folgt.`,`Pings kosten Ladung (Kreise oben rechts). Leere Ladungen füllen sich nach ein paar Sekunden wieder.`,`Perlen bringen Punkte (goldene Perlen viel mehr), jeder Meter Tiefe zählt einen Punkt. Ein Stoß kostet ein Herz.`,`Die Höhle wird mit der Tiefe enger und schneller. Im Modus „Tiefsee“ hat dein Boot keine Lampe – dafür lädt das Sonar schneller und Perlen zählen doppelt.`],tips:[`Ping lieber regelmäßig als hektisch: Der Ring zeigt dir die nächsten Kurven etwa zwei Sekunden lang.`,`Bleib in der Tunnelmitte – dort hast du nach beiden Seiten Platz.`,`Minen piepen tief, wenn der Ring sie trifft. Neben jeder Mine ist immer genug Platz zum Vorbeifahren.`]},"kreuz-und-quer":{goal:`Sammle mehr Punkte als dein Gegner. Ihr teilt euch einen Stein: Du („Quer“) nimmst Zahlen nur aus seiner Zeile, dein Gegner („Kreuz“) nur aus seiner Spalte.`,steps:[`Tippe eine Zahl in der hervorgehobenen Linie an. Du bekommst ihren Wert – Minuszahlen ziehen Punkte ab!`,`Das Feld wird leer und der Stein springt dorthin. Jetzt wählt der andere aus der Linie, die durch das neue Feld läuft.`,`Leere Felder werden einfach übersprungen. Ist deine Linie ganz leer, musst du aussetzen – der andere ist nochmal dran.`,`Können beide nicht mehr, ist die Partie vorbei. Wer mehr Punkte hat, gewinnt.`],tips:[`Schau immer auch in die Linie, die du dem Gegner öffnest: Eine 6 zu nehmen ist besser als eine 9, wenn er danach eine 9 bekäme.`,`Manchmal lohnt sich eine Minuszahl – wenn dem Gegner danach nur noch Minuszahlen bleiben.`,`Gegen Ende zählt jede Linie: Wer den anderen zum Aussetzen zwingt, darf zweimal hintereinander nehmen.`],example:{title:`Welche Zahl nehmen?`,legend:g,frames:[{grid:[`5m84`,`bSgf`,`91n3`,`4682`],note:`Der Stein steht in Zeile 2. Du bist Quer: Du darfst die 2, die 7 oder die 6 nehmen (blau umrandet).`},{grid:[`5mH4`,`2.S6`,`91x3`,`46H2`],note:`Nimmst du die 7, springt der Stein mit – und Kreuz wählt aus dieser Spalte: Er schnappt sich eine 8. Ärgerlich!`},{grid:[`5m8D`,`2.7S`,`91nC`,`468B`],note:`Besser: Nimm die 6. In ihrer Spalte liegt für Kreuz höchstens eine 4 – und die 7 bleibt vielleicht für dich.`}]}},spiegelstrahl:{goal:`Dreh die Spiegel so, dass der Laser jeden Kristall trifft – ohne eine Bombe zu treffen.`,steps:[`Der Laser steht am Rand und schießt geradeaus ins Feld. Spiegel lenken den Strahl um eine Ecke.`,`Tippe einen Spiegel an, um ihn zu drehen (zwischen „/“ und „\\“). Spiegel mit zwei Punkten sind fest und lassen sich nicht drehen.`,`Kristalle leuchten, wenn der Strahl hindurchgeht – er läuft danach weiter. Mauern schlucken den Strahl, Bomben explodieren.`,`Halbdurchlässige Spiegel (lila) lenken den Strahl ab und lassen ihn zugleich durch – danach gibt es zwei Strahlen.`,`Gelöst, wenn alle Kristalle leuchten und keine Bombe getroffen ist. Sterne gibt es für wenige Drehungen (Richtwert oben).`],tips:[`Arbeite vom Laser aus: Wohin muss der Strahl am ersten Spiegel, damit er überhaupt in die Nähe eines Kristalls kommt?`,`Oder rückwärts: Von welchem Spiegel aus kann ein Kristall überhaupt erreicht werden?`,`Nicht jeder Spiegel wird gebraucht – manche sind nur Ablenkung.`,`Auf „Schwer“ gibt es genau eine Lösung.`],example:{title:`Ein Spiegel, ein Kristall`,legend:v,frames:[{grid:[` .C..`,`L-\\.B`,` .|..`,` .|..`],note:`Der Laser schießt nach rechts. Der Spiegel lenkt ihn nach unten – am Kristall vorbei.`},{grid:[` .c..`,`L-/.B`,` ....`,` ....`],note:`Ein Tipp dreht den Spiegel: Jetzt geht der Strahl nach oben und lässt den Kristall leuchten. Gelöst!`},{grid:[` .c..`,`L-s-b`,` ....`,` ....`],note:`Vorsicht mit halbdurchlässigen Spiegeln: Ein Teil des Strahls läuft weiter – hier genau in die Bombe. Bumm!`}]}},gluehwuermchen:{goal:`Fang mit Schlingen so viele Glühwürmchen wie möglich – am besten viele von derselben Farbe auf einmal.`,steps:[`Leg den Finger auf die Wiese und zieh einen Faden. Kreuzt er sich oder kommst du zurück zum Anfang (Kreis), schließt sich die Schlinge.`,`Alle Glühwürmchen in der Schlinge sind gefangen. Gleiche Farbe: Anzahl × Anzahl × 10 Punkte (3 Gelbe = 90). Gemischt gibt es nur 5 je Tier.`,`Goldene Glühwürmchen zählen als jede Farbe und verdoppeln die Schlinge. Mehrere gleichfarbige Schlingen hintereinander steigern die Kombo bis ×2.`,`Wespen zerreißen den Faden, wenn sie ihn berühren. Fängst du eine Wespe ein, sticht sie: Zeitjagd −8 Sekunden, Laterne verliert Licht.`,`Der Faden ist begrenzt (Balken unten). Du kannst nach einer Schlinge gleich weiterziehen.`],tips:[`Warte kurz, bis sich mehrere gleiche Farben nähern – eine Schlinge mit 5 Gelben bringt 250 Punkte, fünf einzelne nur 25.`,`Kleine, schnelle Kreise sind sicherer als große, wenn Wespen in der Nähe sind.`,`Laterne: Jedes gefangene Glühwürmchen füllt das Licht nach, reine Farben füllen mehr. Lieber oft kleine Schlingen als zu lange auf die perfekte warten.`]},"auf-und-ab":{goal:`Ihr spielt zusammen gegen das Spiel: Legt alle 98 Karten (2–99) auf vier Stapel. Zwei Stapel steigen ab 1, zwei fallen ab 100. Je weniger Karten am Ende übrig sind, desto besser – unter 10 ist hervorragend, 0 heißt gewonnen.`,steps:[`Auf einen steigenden Stapel (▲) darf nur eine höhere Karte, auf einen fallenden (▼) nur eine niedrigere. Wie groß der Sprung ist, ist egal – aber jede übersprungene Zahl ist für diesen Stapel verloren.`,`Rückwärtstrick: Eine Karte, die genau 10 niedriger (▲) bzw. genau 10 höher (▼) ist als die oberste, darf immer gelegt werden. So bekommt ein Stapel wieder Luft.`,`Wer dran ist, legt mindestens 2 Karten (Profi: 3), darf aber mehr legen. Danach „Zug beenden“ – die Hand wird wieder aufgefüllt. Ist der Nachziehstapel leer, reicht 1 Karte.`,`Bedienen: Karte antippen, dann den Stapel – oder die Karte zweimal antippen, dann landet sie auf dem günstigsten Stapel. „Zurück“ nimmt eine Karte dieses Zugs zurück.`,`Kann jemand nicht mehr genug Karten legen, ist die Partie vorbei. Gezählt wird, was noch auf den Händen und im Nachziehstapel liegt.`,`Zahlen verraten ist verboten! Erlaubt sind Absprachen: Mit ✋ an einem Stapel sagst du „Bitte frei lassen, ich habe hier etwas Gutes“. Die NPCs machen das auch.`,`Feuer: 22, 33, 44, 55, 66 und 77 brennen. Liegt eine oben, muss sie bis zum Ende des nächsten Zugs abgedeckt sein – sonst ist sofort alles verloren.`,`Allein: 8 Karten auf der Hand. Zu zweit: 7, ab drei Spielern: 6. „Zusammen“ = ein Handy wird weitergegeben, die Karten bleiben dabei verdeckt.`],tips:[`Merk dir, was schon liegt: Wenn 31–34 längst gelegt sind, kostet der Sprung von 30 auf 35 gar nichts.`,`Spar dir Paare mit Abstand 10 (z. B. 47 und 37) für einen Rückwärtstrick auf.`,`Leg lieber nur die Pflichtkarten, wenn alles andere große Sprünge wären – die nächste Runde bringt neue Karten.`,`Achte auf die ✋ der anderen: Wer einen Stapel reserviert, hat dort eine Karte, die fast nichts kostet.`],example:{title:`Ein Zug`,legend:{A:a(e,`12`),B:a(e,`30`),C:a(t,`88`),D:a(t,`61`),E:{...a(e,`15`),ring:n},F:{...a(t,`71`),ring:n},h:a(n,`15`),i:a(n,`20`),j:a(n,`71`),k:a(n,`40`),m:a(n,`93`),n:a(n,`8`)},frames:[{grid:[`ABCD`,`hijk`],note:`Oben die Stapel: blau steigt (▲), pink fällt (▼). Unten deine Hand: 15, 20, 71, 40.`},{grid:[`EBCD`,`.ijk`],note:`15 auf die steigende 12: nur 13 und 14 übersprungen – ein guter Zug.`},{grid:[`EBCF`,`.i.k`],note:`71 auf die fallende 61: genau 10 höher – Rückwärtstrick! Der Stapel hat wieder Luft.`},{grid:[`EBCF`,`mink`],note:`Zwei Karten gelegt → „Zug beenden“. Die Hand wird aufgefüllt (93 und 8), der Nächste ist dran.`}]}},kronen:{goal:`Setze Kronen so, dass in jeder Zeile, jeder Spalte und jeder Farbe genau eine Krone steht. Zwei Kronen dürfen sich nie berühren – auch nicht schräg.`,steps:[`Tippe ein Feld an: einmal = Kreuz (hier kommt sicher keine Krone hin), zweimal = Krone, dreimal = wieder leer.`,`Wische über leere Felder, um viele Kreuze auf einmal zu setzen.`,`Stören sich zwei Kronen (gleiche Zeile, Spalte, Farbe oder sie berühren sich), werden sie rot.`,`„Auto-✕“ kreuzt beim Setzen einer Krone alles aus, was sie ausschließt. „Zurück“ nimmt den letzten Schritt zurück.`,`Level: Sterne für schnelles Lösen. Täglich: ein Rätsel pro Tag für alle. Blitz: so viele Rätsel wie möglich in 3 Minuten.`],tips:[`Fang bei kleinen Farben an: Eine Farbe mit nur zwei, drei Feldern hat kaum Möglichkeiten.`,`Liegt eine ganze Farbe in einer einzigen Zeile, gehört deren Krone in diese Zeile – alle anderen Felder der Zeile bekommen ein Kreuz.`,`Zwei Farben, die zusammen nur in zwei Spalten liegen, belegen diese beiden Spalten. Für andere Farben ist dort kein Platz mehr.`,`Jedes Rätsel ist ohne Raten lösbar.`],example:{title:`Ein kleines 4×4-Rätsel`,legend:{a:{bg:l},b:{bg:u},c:{bg:d},d:{bg:f},A:p(l),B:p(u),C:p(d),D:p(f),1:m(l),2:m(u),3:m(d),4:m(f)},frames:[{grid:[`aabb`,`aacb`,`dccb`,`ddcc`],note:`Vier Farben, vier Zeilen, vier Spalten – in jede gehört genau eine Krone.`},{grid:[`1abb`,`11cb`,`D332`,`44cc`],note:`Eine Krone unten links in Gelb schließt ihre Zeile, ihre Spalte, ihre Farbe und alle Nachbarfelder aus: Kreuze!`},{grid:[`1A22`,`113b`,`D332`,`44cc`],note:`Für Rot bleibt nur ein Feld – dort muss die Krone hin. Wieder fallen ihre Zeile und ihre Nachbarn weg.`},{grid:[`1A22`,`113B`,`D332`,`44C3`],note:`Grün und Blau haben jetzt je nur noch einen Platz. Vier Kronen, keine berührt sich: gelöst!`}]}},weichensteller:{goal:`Bring jeden Zug in den Bahnhof seiner Farbe, indem du rechtzeitig die Weichen umstellst.`,steps:[`Züge kommen unten aus dem Tunnel und fahren über das Gleisnetz nach oben. An jeder Weiche (gelber Kreis) biegen sie dorthin ab, wohin der gelbe Pfeil zeigt.`,`Tippe auf eine Weiche, um sie umzustellen – das geht jederzeit, auch kurz bevor ein Zug ankommt.`,`Jeder Zug hat Farbe und Zeichen seines Bahnhofs. Kommt er richtig an, gibt es einen grünen Haken, sonst ein rotes Kreuz.`,`Gold-Loks sind Express-Züge (anderthalbmal so schnell). Bunte Züge sind Joker – sie dürfen in jeden Bahnhof.`,`Level: ab 70 % richtig geschafft, 3 Sterne für alle Züge richtig. Endlos: immer schneller, nach 3 Fehlern ist Schluss.`],tips:[`Schau nicht nur auf den vordersten Zug – stell die erste Weiche schon für den nächsten, sobald der vorige durch ist.`,`Ab Level 21 gibt es zwei Tunnel mit getrennten Netzen. Beide im Blick behalten!`]},orbitduell:{goal:`Triff das Raumschiff des Gegners dreimal, bevor er dich dreimal trifft. Allein (Zielübung): Triff alle Satelliten mit wenigen Schüssen.`,steps:[`Leg den Finger irgendwo aufs Spielfeld und zieh ihn zurück – wie bei einer Steinschleuder. Je weiter, desto schneller der Schuss. Loslassen = Feuer.`,`Die gestrichelte Linie zeigt den Anfang der Flugbahn. Planeten ziehen das Geschoss an, Schwarze Löcher sehr stark, der türkise Abstoßer drückt es weg.`,`Planeten verschlucken Geschosse, Asteroiden gehen bei einem Treffer kaputt. Pass auf: Ein Schuss, der um einen Planeten herumkommt, kann auch dich selbst treffen!`,`Waffen: Kugel (unbegrenzt), Drilling (2×, drei Kugeln im Fächer) und Brocken (1×, zählt doppelt). Erst Waffe antippen, dann schießen.`,`Nach 40 Schüssen ohne Sieger gewinnt, wer mehr Leben übrig hat.`],tips:[`Merk dir deinen letzten Schuss: Hat er knapp links vorbeigeschossen, ziehst du beim nächsten etwas weiter nach rechts.`,`Oft trifft ein weiter Bogen um den Planeten herum besser als der direkte Weg.`,`Den Drilling lohnt es sich zu nehmen, wenn du schon fast triffst – die Seitenkugeln gleichen kleine Fehler aus.`]},brueckenbau:{goal:`Verbinde alle Inseln mit Brücken zu einem einzigen Netz. Jede Insel braucht genau so viele Brücken, wie ihre Zahl sagt.`,steps:[`Tippe zwischen zwei Inseln, um eine Brücke zu bauen. Nochmal tippen macht eine Doppelbrücke, ein drittes Mal reißt sie wieder ab. Du kannst auch von einer Insel aus in eine Richtung wischen.`,`Brücken laufen nur gerade (waagerecht oder senkrecht) und dürfen sich nicht kreuzen.`,`Zwischen zwei Inseln passen höchstens zwei Brücken.`,`Eine Insel wird grün, wenn ihre Zahl stimmt – und rot, wenn sie zu viele Brücken hat.`,`Gelöst ist das Rätsel erst, wenn alle Zahlen stimmen UND man über die Brücken von jeder Insel zu jeder anderen kommt.`],tips:[`Fang bei Inseln an, die keine Wahl haben: Eine 1 am Rand mit nur einem Nachbarn, eine 4 in der Ecke (zwei Nachbarn = je zwei Brücken) oder eine 8 in der Mitte.`,`Zwei Einsen dürfen sich nicht nur gegenseitig verbinden – sonst hängen sie vom Rest ab.`],example:{title:`Die 4 in der Ecke`,legend:{4:a(e,`4`),2:a(e,`2`),3:a(e,`3`),1:a(e,`1`),G:a(r,`4`),"=":{text:`═`,color:`#fbbf24`},H:{text:`║`,color:`#fbbf24`},"|":{text:`│`,color:`#fbbf24`}},frames:[{grid:[`4..3`,`....`,`2..1`],note:`Die 4 oben links hat nur zwei Nachbarn: die 3 rechts und die 2 unten.`},{grid:[`G==3`,`H...`,`2..1`],note:`Also braucht sie zu beiden eine Doppelbrücke – anders kommt sie nie auf 4.`},{grid:[`G==3`,`H..|`,`2..1`],note:`Die 2 ist damit schon fertig. Die 3 braucht noch eine Brücke – die geht nach unten zur 1. Alles hängt zusammen: gelöst!`}]}},wortsuche:{goal:`Finde alle Wörter aus der Liste im Buchstabenfeld. Alle Wörter gehören zum selben Thema.`,steps:[`Wische vom ersten bis zum letzten Buchstaben über ein Wort – oder tippe erst den Anfangs- und dann den Endbuchstaben an.`,`Wörter stehen in gerader Linie: auf „Leicht“ nur von links nach rechts und von oben nach unten, ab „Mittel“ auch schräg, auf „Schwer“ zusätzlich rückwärts.`,`Gefundene Wörter werden farbig markiert und in der Liste durchgestrichen. Wörter dürfen sich einen Buchstaben teilen.`,`Klassisch: ein Feld, die Uhr läuft für die Bestzeit. Blitz: 3 Minuten, so viele Wörter wie möglich. Täglich: ein Feld pro Tag, für alle gleich.`],tips:[`Such nach seltenen Buchstaben wie Ä, Ö, Ü, Z, K oder V – die stehen kaum zufällig herum.`,`Der Tipp-Knopf umrandet den Anfangsbuchstaben eines fehlenden Worts.`],example:{legend:{H:a(t,`H`),U:a(t,`U`),N:a(t,`N`),D:a(t,`D`),h:{text:`H`},u:{text:`U`},n:{text:`N`},d:{text:`D`},a:{text:`A`},k:{text:`K`},e:{text:`E`},s:{text:`S`},t:{text:`T`},r:{text:`R`}},frames:[{grid:[`kahst`,`ehund`,`srate`,`tensk`],note:`Gesucht: HUND. Wo steht ein H mit einem U daneben?`},{grid:[`kahst`,`eHUND`,`srate`,`tensk`],note:`Gefunden! Vom H bis zum D wischen – fertig.`}]}},backgammon:{goal:`Bring alle deine Steine in dein Heimfeld (das Viertel unten rechts) und würfle sie dann hinaus. Wer zuerst keinen Stein mehr auf dem Brett hat, gewinnt.`,steps:[`Es wird automatisch gewürfelt. Jeder Würfel ist ein eigener Zug: Bei 5 und 3 ziehst du einen Stein 5 Felder und einen (denselben oder einen anderen) 3 Felder. Bei einem Pasch darfst du viermal ziehen.`,`Tippe einen Stein an (gelbe Punkte zeigen, welche ziehen können), dann das markierte Zielfeld. Deine Steine laufen im Bogen: oben von rechts nach links, dann unten von links nach rechts ins Heimfeld.`,`Ein Feld mit zwei oder mehr gegnerischen Steinen ist gesperrt. Steht dort nur EIN gegnerischer Stein, schlägst du ihn: Er muss auf die Bar (Mitte) und von ganz vorn neu anfangen.`,`Hast du selbst Steine auf der Bar, musst du sie zuerst wieder einsetzen. Sind alle Einsatzfelder gesperrt, setzt du aus.`,`Erst wenn alle deine Steine im Heimfeld stehen, darfst du sie hinauswürfeln (rechts auf die Ablage tippen).`,`Du musst beide Würfel benutzen, wenn es irgendwie geht. Geht nur einer, dann der höhere.`],tips:[`Lass Steine möglichst zu zweit stehen – ein einzelner Stein kann geschlagen werden.`,`Mehrere besetzte Felder nebeneinander bilden eine Mauer, an der der Gegner nicht vorbeikommt.`,`Hat der Verlierer noch keinen Stein draußen, zählt der Sieg doppelt („Gammon“).`]},eisstock:{goal:`Leg deine Steine näher an die Mitte der Ringe als dein Gegner. Gewertet wird nach jeder Kehre (wenn alle Steine geworfen sind).`,steps:[`Finger aufs Eis setzen und nach hinten (unten) ziehen – wie bei einer Schleuder. Je weiter du ziehst, desto fester der Wurf; seitlich ziehen zielt. Loslassen wirft.`,`Die gestrichelte Linie zeigt, wie weit der Stein ungefähr gleitet, wenn er nichts trifft.`,`Steine stoßen sich gegenseitig weg. So kannst du gegnerische Steine aus den Ringen schubsen oder eigene nach vorn schieben.`,`Ein Stein, der die Mindestweite (gestrichelte Querlinie) nicht erreicht oder über die Bande rutscht, ist raus.`,`Wertung: Nur wer den Stein hat, der der Mitte am nächsten liegt, bekommt Punkte – einen für jeden eigenen Stein, der näher liegt als der beste des Gegners.`,`Wer gepunktet hat, muss in der nächsten Kehre anfangen. Der andere hat dann den wertvollen letzten Stein.`],tips:[`Der letzte Stein der Kehre entscheidet oft alles.`,`Ein Stein kurz vor den Ringen schützt die Steine dahinter wie eine Mauer.`,`Allein spielst du auf Punkte: Mitte 10, mittlerer Ring 6, äußerer Ring 3.`]},pfeilwirbel:{goal:`Wirf alle Pfeile einer Runde in die drehende Scheibe, ohne einen steckenden Pfeil zu treffen.`,steps:[`Tippe irgendwo: Der Pfeil fliegt gerade nach oben und bleibt unten in der Scheibe stecken.`,`Triffst du einen Pfeil, der schon steckt, kostet das ein Herz. Ohne Herzen ist Schluss.`,`Unten links siehst du, wie viele Pfeile die Runde noch braucht. Ist die Scheibe voll, kommt die nächste – schneller, mit schon steckenden Pfeilen oder mit Tempo-Wechseln.`,`Äpfel am Rand geben 3 Extrapunkte, eine volle Scheibe 5, jede fünfte ist eine Boss-Scheibe mit 10.`],tips:[`Achte auf die Lücke, die gleich unten ankommt – nicht auf die, die gerade dort ist. Der Pfeil braucht einen Moment.`,`Bei „Vor und zurück“ und „Stop and go“ lieber warten, bis die Scheibe gleichmäßig läuft.`]},reversi:{goal:`Am Ende mehr Steine der eigenen Farbe auf dem Brett haben als der Gegner.`,steps:[`Setze einen Stein so, dass du mindestens einen gegnerischen Stein in gerader Linie (waagerecht, senkrecht oder schräg) zwischen deinem neuen und einem eigenen alten Stein einklemmst.`,`Alle eingeklemmten Steine werden umgedreht und gehören jetzt dir.`,`Kannst du nirgends einklemmen, setzt du aus. Kann niemand mehr ziehen, wird gezählt.`],tips:[`Ecken können nie mehr umgedreht werden – sichere sie dir.`,`Felder direkt neben einer freien Ecke sind gefährlich: Sie schenken dem Gegner oft die Ecke.`],example:{legend:s,frames:[{grid:[`....`,`.bp.`,`.pb.`,`....`],note:`Blau ist dran. Wo lässt sich ein pinker Stein einklemmen?`},{grid:[`....`,`.bpo`,`.pb.`,`....`],note:`Rechts neben dem pinken Stein: Dann liegt er zwischen zwei blauen.`},{grid:[`....`,`.bBB`,`.pb.`,`....`],note:`Der eingeklemmte Stein wird umgedreht und ist jetzt blau.`}]}},muehle:{goal:`Bilde „Mühlen“ (drei eigene Steine in einer Linie) und nimm dem Gegner damit Steine weg, bis er nur noch zwei hat oder nicht mehr ziehen kann.`,steps:[`Setzphase: Abwechselnd setzt jeder seine neun Steine auf freie Punkte.`,`Zugphase: Danach ziehst du pro Zug einen Stein entlang einer Linie auf einen freien Nachbarpunkt.`,`Jede neue Mühle erlaubt dir, einen gegnerischen Stein vom Brett zu nehmen. Steine in einer geschlossenen Mühle sind geschützt, solange es andere gibt.`,`Wer nur noch drei Steine hat, darf springen: mit einem Stein auf jeden beliebigen freien Punkt.`],tips:[`Eine „Zwickmühle“ ist Gold wert: Ein Stein, der mit jedem Zug abwechselnd eine von zwei Mühlen schließt.`,`Kreuzungspunkte in der Mitte der Seiten haben die meisten Nachbarn – dort bleibst du beweglich.`]},dame:{goal:`Schlage alle gegnerischen Steine oder sperre sie so ein, dass der Gegner nicht mehr ziehen kann.`,steps:[`Steine ziehen ein Feld schräg nach vorn, immer auf den dunklen Feldern.`,`Schlagen: Spring über einen direkt benachbarten gegnerischen Stein auf das freie Feld dahinter – das geht auch rückwärts. Kannst du danach gleich weiterschlagen, tust du das im selben Zug.`,`Schlagen ist Pflicht! Wer schlagen kann, muss schlagen.`,`Erreicht ein Stein die letzte Reihe, wird er zur Dame. Eine Dame zieht und schlägt schräg beliebig weit – vorwärts und rückwärts.`],tips:[`Biete dem Gegner gezielt einen Stein an, wenn du danach zwei zurückschlagen kannst – er MUSS ja schlagen.`,`Lass deine hinterste Reihe lange stehen, dann bekommt der Gegner keine Dame.`],example:{legend:s,frames:[{grid:[`....`,`..p.`,`.b..`,`....`],note:`Blau zieht nach oben. Der pinke Stein steht schräg davor, dahinter ist frei.`},{grid:[`...B`,`..x.`,`....`,`....`],note:`Blau springt drüber – der pinke Stein ist geschlagen. Das ist Pflicht!`}]}},schach:{goal:`Setze den gegnerischen König schachmatt: Er wird angegriffen und kann dem Angriff nicht mehr entkommen.`,steps:[`Tippe eine Figur an – die möglichen Zielfelder werden markiert – und dann das Ziel.`,`Bauer: ein Feld geradeaus (vom Startfeld aus auch zwei), schlägt aber nur schräg nach vorn. Erreicht er die letzte Reihe, wird er umgewandelt (meist in eine Dame).`,`Turm: gerade Linien. Läufer: Diagonalen. Dame: beides. König: ein Feld in jede Richtung. Springer: „zwei vor, eins zur Seite“ – er darf als einziger über Figuren springen.`,`Steht dein König im Schach, musst du das sofort beheben: wegziehen, die angreifende Figur schlagen oder etwas dazwischenstellen.`,`Sonderzüge: Rochade (König zwei Felder Richtung Turm, der Turm springt drüber – nur wenn beide noch nicht gezogen haben) und en passant (ein Bauer schlägt einen Bauern, der gerade im Doppelschritt an ihm vorbeigezogen ist).`,`Unentschieden gibt es bei Patt (kein Zug möglich, aber kein Schach), dreifacher Stellungswiederholung oder wenn niemand mehr mattsetzen kann.`],tips:[`Zu Beginn: Bauern in die Mitte, Springer und Läufer raus, früh rochieren.`,`Grober Tauschwert: Bauer 1, Springer und Läufer 3, Turm 5, Dame 9.`]},mancala:{goal:`Sammle mehr Steine in deiner großen Mulde (Kalaha, rechts von dir) als der Gegner.`,steps:[`Tippe eine deiner sechs Mulden an. Alle Steine daraus werden gegen den Uhrzeigersinn einzeln auf die folgenden Mulden verteilt – auch in deine Kalaha, aber nicht in die des Gegners.`,`Extrazug: Landet der letzte Stein in deiner Kalaha, bist du gleich nochmal dran.`,`Fang: Landet der letzte Stein in einer leeren Mulde auf deiner Seite, gehören er und alle Steine aus der Mulde gegenüber dir.`,`Sind auf einer Seite alle Mulden leer, endet das Spiel. Die restlichen Steine gehen an den, auf dessen Seite sie liegen.`],tips:[`Zähle vor dem Zug ab: Eine Mulde mit genau so vielen Steinen, wie der Weg bis zur Kalaha lang ist, gibt einen Extrazug.`,`Leere Mulden auf deiner Seite sind Fallen für den Gegner – wenn gegenüber viel liegt.`]},hex:{goal:`Verbinde deine beiden Brettseiten mit einer lückenlosen Kette aus eigenen Sechsecken. Dein Gegner versucht dasselbe quer dazu.`,steps:[`Abwechselnd färbt jeder ein beliebiges freies Feld in seiner Farbe.`,`Einmal gesetzte Felder bleiben für immer. Schlagen gibt es nicht.`,`Es gibt nie ein Unentschieden: Irgendwann ist immer genau eine Kette fertig.`],tips:[`Wer den Gegner blockt, baut dabei fast immer an der eigenen Kette – Angriff und Verteidigung sind hier dasselbe.`,`Zwei Felder mit zwei gemeinsamen freien Nachbarn sind schon „so gut wie verbunden“: Besetzt der Gegner einen, nimmst du den anderen.`]},kaesekaestchen:{goal:`Schließe mehr Kästchen als dein Gegner.`,steps:[`Abwechselnd zieht jeder eine Linie zwischen zwei benachbarten Punkten.`,`Wer die vierte Seite eines Kästchens zieht, bekommt das Kästchen und MUSS direkt nochmal ziehen.`,`Sind alle Linien gezogen, gewinnt, wer mehr Kästchen hat.`],tips:[`Zieh möglichst lange keine dritte Seite an einem Kästchen – die vierte holt sich sonst der Gegner.`,`Am Ende entstehen lange Ketten. Wer gezwungen ist, die erste Kette zu öffnen, verliert meist – versuch, dem Gegner die kurze Kette zu überlassen.`]},"tictactoe-xxl":{goal:`Gewinne drei kleine Tic-Tac-Toe-Felder in einer Reihe.`,steps:[`Das große Brett besteht aus neun kleinen Feldern. In jedem wird normales Tic Tac Toe gespielt.`,`Der Kniff: Das Kästchen, in das du setzt, bestimmt, in welchem kleinen Feld dein Gegner als Nächstes spielen muss. Setzt du unten rechts, muss er ins kleine Feld unten rechts.`,`Wer in einem kleinen Feld drei in einer Reihe hat, gewinnt dieses Feld.`,`Wirst du in ein Feld geschickt, das schon entschieden oder voll ist, darfst du frei wählen.`],tips:[`Denk vor jedem Zug daran, wohin du den Gegner schickst – das ist oft wichtiger als der Zug selbst.`]},"fuenf-in-reihe":{goal:`Bilde als Erster eine Reihe aus fünf eigenen Steinen – waagerecht, senkrecht oder schräg.`,steps:[`Abwechselnd setzt jeder einen Stein auf einen freien Punkt.`,`Steine werden nie bewegt oder geschlagen.`],tips:[`Eine Viererreihe mit einem freien Ende muss sofort geblockt werden.`,`Eine Dreierreihe mit ZWEI freien Enden ist schon eine Drohung: Wird sie zur offenen Vier, ist sie nicht mehr aufzuhalten.`,`Gewinnen tut meist, wer zwei Drohungen gleichzeitig baut.`]},klonkrieg:{goal:`Wenn das Brett voll ist (oder niemand mehr ziehen kann), mehr Steine haben als der Gegner.`,steps:[`Tippe einen eigenen Stein an und dann ein freies Feld in der Nähe.`,`Klonen: Auf ein direkt benachbartes Feld (auch schräg) – der alte Stein bleibt stehen, du hast einen mehr.`,`Springen: Zwei Felder weit – der Stein verlässt seinen Platz.`,`Danach werden alle gegnerischen Steine rund um das Zielfeld zu deinen.`],tips:[`Klonen ist fast immer besser als Springen – beim Springen entsteht hinter dir eine Lücke, in die der Gegner klonen kann.`],example:{legend:s,frames:[{grid:[`.....`,`.b.p.`,`...p.`,`.....`],note:`Blau ist dran: Das Feld zwischen dem blauen und den pinken Steinen ist ein Nachbarfeld.`},{grid:[`.....`,`.bBp.`,`...p.`,`.....`],note:`Klonen: Ein neuer blauer Stein entsteht, der alte bleibt.`},{grid:[`.....`,`.bBB.`,`...B.`,`.....`],note:`Alle pinken Nachbarn des neuen Steins werden blau.`}]}},kettenreaktion:{goal:`Erobere alle Felder des Gegners.`,steps:[`Tippe ein leeres oder eigenes Feld an, um eine Kugel hineinzulegen. Felder des Gegners darfst du nicht antippen.`,`Jedes Feld fasst so viele Kugeln, wie es Nachbarn hat, minus eins: Ecken 1, Ränder 2, Felder in der Mitte 3.`,`Wird ein Feld zu voll, platzt es: Je eine Kugel fliegt in jedes Nachbarfeld – und macht es zu deinem, samt allen Kugeln darin.`,`Dadurch können Nachbarfelder gleich mitplatzen: eine Kettenreaktion.`],tips:[`Ecken platzen schon bei der zweiten Kugel – ideale Zünder.`,`Volle Felder neben vollen Feldern des Gegners sind ein Wettlauf: Wer zuerst zündet, bekommt alles.`]},durchbruch:{goal:`Bring als Erster einen Bauern auf die Grundreihe des Gegners.`,steps:[`Ein Bauer zieht ein Feld nach vorn: geradeaus oder schräg – aber nur auf freie Felder.`,`Schlagen geht NUR schräg nach vorn. Ein Bauer direkt vor dir blockiert dich.`,`Schlagen ist keine Pflicht.`],tips:[`Halte deine hintere Reihe geschlossen – eine Lücke dort reicht dem Gegner zum Durchbruch.`,`Bauern in Zweierreihen decken sich gegenseitig: Wer einen schlägt, wird zurückgeschlagen.`],example:{legend:s,frames:[{grid:[`.p.`,`.b.`,`...`],note:`Blau zieht nach oben. Der pinke Bauer steht direkt davor: geradeaus geht es nicht.`},{grid:[`Bp.`,`...`,`...`],note:`Schräg vorbei geht aber – und Blau steht auf der gegnerischen Grundreihe: gewonnen!`}]}},bauherren:{goal:`Steig mit einem deiner beiden Baumeister auf ein Gebäude der Stufe 3.`,steps:[`Zu Beginn stellt jeder seine zwei Baumeister auf freie Felder.`,`Ein Zug hat immer zwei Teile: erst ZIEHEN, dann BAUEN.`,`Ziehen: ein Feld in jede Richtung (auch schräg). Dabei höchstens eine Stufe nach oben, nach unten beliebig tief. Nicht auf Kuppeln oder besetzte Felder.`,`Bauen: Auf ein Nachbarfeld des gezogenen Baumeisters kommt eine Stufe drauf. Auf Stufe 3 wird eine Kuppel gebaut – dieses Feld ist dann gesperrt.`,`Wer keinen Zug mit anschließendem Bauen mehr hat, verliert.`],tips:[`Steht der Gegner auf Stufe 2 neben einer Stufe 3, musst du sofort eine Kuppel draufsetzen.`,`Bau dir selbst Treppen: Stufe 1 und 2 nebeneinander, dann kommt die 3 fast von allein.`]},schubkampf:{goal:`Schiebe sechs gegnerische Kugeln über den Brettrand.`,steps:[`Du bewegst pro Zug eine, zwei oder drei eigene Kugeln, die in einer Linie nebeneinander liegen, gemeinsam um ein Feld.`,`In Längsrichtung darfst du dabei gegnerische Kugeln schieben – aber nur, wenn du in der Überzahl bist: 2 gegen 1, 3 gegen 1 oder 3 gegen 2.`,`Hinter den geschobenen Kugeln muss ein freies Feld oder der Rand sein. Fällt eine Kugel über den Rand, ist sie raus.`,`Seitwärtsschritte (die Reihe rückt quer) sind erlaubt, schieben aber nichts.`],tips:[`Bleib in der Mitte und kompakt – am Rand lebt es sich gefährlich.`,`Dreierreihen kann der Gegner nie zurückschieben.`]},drehkreuz:{goal:`Bilde fünf eigene Kugeln in einer Reihe – waagerecht, senkrecht oder schräg.`,steps:[`Ein Zug hat zwei Teile: Erst setzt du eine Kugel in eine freie Mulde …`,`… dann drehst du eines der vier Brett-Viertel um 90° nach links oder rechts. Die Drehung ist Pflicht.`,`Fünf in Reihe können auch erst durch die Drehung entstehen. Haben danach beide eine Fünferreihe, ist es unentschieden.`],tips:[`Die Mitte jedes Viertels dreht sich nie mit – gute Ankerpunkte.`,`Prüf vor dem Drehen, ob du dem Gegner nicht gerade eine Reihe zusammenschiebst.`]},mauerrennen:{goal:`Erreiche als Erster mit deiner Figur die gegenüberliegende Brettseite.`,steps:[`Pro Zug machst du EINS von beiden: einen Schritt gehen ODER eine Mauer setzen.`,`Gehen: ein Feld nach oben, unten, links oder rechts. Steht der Gegner direkt vor dir, darfst du über ihn springen.`,`Mauer: Sie ist zwei Felder lang und sperrt den Weg dazwischen. Dein Vorrat ist begrenzt.`,`Niemand darf ganz eingesperrt werden – es muss immer ein Weg zum Ziel übrig bleiben.`],tips:[`Mauern verlängern den Weg des Gegners – setz sie dort, wo sie ihn die meisten Schritte kosten, nicht einfach direkt vor seine Nase.`,`Heb dir ein paar Mauern fürs Ende auf.`]},dominoblock:{goal:`Lege so lange Dominosteine, bis dein Gegner keinen Platz mehr für seinen findet.`,steps:[`Blau legt seine Steine immer senkrecht (zwei Felder übereinander), Pink immer waagerecht (zwei nebeneinander).`,`Tippe ein freies Feld an – die Vorschau zeigt den Stein – und tippe nochmal zum Legen.`,`Wer dran ist und keinen Stein mehr unterbringt, hat verloren.`],tips:[`Schaffe dir Plätze, die nur DU nutzen kannst: Blau liebt schmale senkrechte Schächte, Pink schmale waagerechte Gänge.`],example:{legend:{b:a(e),p:a(t),B:a(e,``,`#000`),o:o()},frames:[{grid:[`pp..`,`b...`,`b.pp`,`....`],note:`Blau (senkrecht) ist dran.`},{grid:[`ppb.`,`b.b.`,`b.pp`,`....`],note:`Blau legt in die Lücke – jetzt passt oben rechts kein waagerechter Stein mehr hin.`}]}},sprungjagd:{goal:`Mach den letzten Zug: Wer nicht mehr springen kann, verliert.`,steps:[`Das Brett ist am Anfang ganz voll. Zur Eröffnung nimmt jeder einen Stein weg (die erlaubten sind markiert).`,`Danach wird nur noch gesprungen: mit einem eigenen Stein gerade (nicht schräg) über einen direkt benachbarten gegnerischen Stein auf das freie Feld dahinter. Der übersprungene Stein ist weg.`,`Geht es in derselben Richtung gleich weiter, darfst du mehrere Steine hintereinander überspringen.`],tips:[`Es zählt nicht, wer mehr Steine hat – nur, wer am Ende noch springen kann. Halte dir Sprünge für später offen.`],example:{legend:s,frames:[{grid:[`bp.p.`,`.....`],note:`Blau kann über den ersten pinken Stein springen …`},{grid:[`.xBp.`,`.....`],note:`… landet dahinter – und dahinter steht schon der nächste mit freiem Feld.`},{grid:[`...xB`,`.....`],note:`Also gleich weiter in derselben Richtung: zwei Steine in einem Zug.`}]}},matroschka:{goal:`Drei eigene Figuren in einer Reihe (von oben gesehen).`,steps:[`Jeder hat Figuren in drei Größen. Pro Zug setzt du eine neue Figur ein ODER versetzt eine eigene, die schon auf dem Brett steht.`,`Eine größere Figur darf über eine kleinere gestülpt werden – auch über eine gegnerische. Die verdeckte Figur zählt dann nicht mehr.`,`Vorsicht beim Versetzen: Hebst du eine Figur hoch, kommt die darunter wieder zum Vorschein. Legst du damit eine Dreierreihe des Gegners frei, hast du verloren.`],tips:[`Merk dir, was unter deinen großen Figuren steckt.`,`Die größten Figuren kann niemand mehr verdecken – setz sie nicht zu früh.`]},linienkampf:{goal:`Verbinde alle deine Steine zu einer einzigen zusammenhängenden Gruppe (auch schräg zählt als verbunden).`,steps:[`Ein Stein zieht in gerader Linie – waagerecht, senkrecht oder schräg.`,`Er zieht GENAU so viele Felder, wie insgesamt Steine (eigene und fremde) auf dieser Linie stehen.`,`Über eigene Steine darfst du springen, über gegnerische nicht.`,`Landest du auf einem gegnerischen Stein, ist er geschlagen.`],tips:[`Schlagen hilft dem Gegner manchmal: Mit weniger Steinen ist er schneller verbunden.`,`Ein einzelner übrig gebliebener Stein gilt als verbunden.`],example:{legend:s,frames:[{grid:[`.....`,`B.p.b`,`.....`],note:`In dieser Zeile stehen drei Steine. Der linke blaue müsste waagerecht also genau drei Felder ziehen.`},{grid:[`.....`,`B.px.`,`.....`],note:`Geht aber nicht: Dabei müsste er über den pinken Stein springen – das ist verboten.`},{grid:[`.B...`,`..p.b`,`.....`],note:`Auf der Schrägen steht nur er selbst: also genau ein Feld schräg. Jede Linie hat ihre eigene Zuglänge.`}]}},minenduell:{goal:`Mehr Punkte sichern als dein Gegner – auf einem gemeinsamen Minenfeld.`,steps:[`Wer dran ist, deckt Felder auf. Jedes sichere Feld bringt Punkte, die erst einmal „auf dem Tisch“ liegen.`,`Nach jedem Feld entscheidest du: „Sichern“ (die Punkte gehören dir, der andere ist dran) oder weiter aufdecken.`,`Triffst du eine Mine, sind alle Punkte dieses Zugs weg und der andere ist dran.`,`Die Zahlen bedeuten wie beim Minensucher: So viele Minen liegen in den acht Nachbarfeldern.`,`Das allererste Aufdecken ist eine freie Eröffnung: immer sicher, aber ohne Punkte.`],tips:[`Felder, die sicher sind, sind sicher für BEIDE – was du dir nicht holst, nimmt der Gegner.`]},pfadleger:{goal:`Bleib als Letzter mit deiner Figur auf dem Brett.`,steps:[`Du hast Plättchen mit Wegen auf der Hand. Wähle eins, dreh es, wie du magst, und leg es auf das Feld direkt vor deiner Figur.`,`Deine Figur folgt dann sofort ihrem Weg – so weit, wie Plättchen liegen.`,`Auch andere Figuren, die an dieses Feld grenzen, müssen dem neuen Weg folgen.`,`Wer vom Brett läuft oder mit einer anderen Figur zusammenstößt, ist raus.`],tips:[`Schau vor dem Legen, wohin der Weg dich am Ende führt – am besten weg vom Rand.`,`Steht ein Gegner am selben Feld, kannst du ihm einen Weg nach draußen legen.`]},"vier-gewinnt":{goal:`Bringe vier eigene Steine in eine Reihe – waagerecht, senkrecht oder schräg.`,steps:[`Tippe eine Spalte an: Dein Stein fällt bis ganz nach unten.`,`Abwechselnd ziehen, bis jemand vier in einer Reihe hat oder das Brett voll ist.`],tips:[`Die mittlere Spalte ist am wertvollsten: Von dort gehen die meisten Reihen aus.`,`Bau zwei Drohungen gleichzeitig – der Gegner kann nur eine blocken.`]},"schiffe-versenken":{goal:`Versenke alle Schiffe des Gegners, bevor er deine findet.`,steps:[`Stelle zuerst deine Flotte auf (oder tippe auf „Zufällig“).`,`Dann tippst du abwechselnd mit dem Gegner auf ein Feld seines Rasters: Treffer oder Wasser.`,`Ein Schiff ist versenkt, wenn alle seine Felder getroffen sind.`],tips:[`Nach einem Treffer die Nachbarfelder absuchen, bis das Schiff versenkt ist.`,`Schieß im Schachbrettmuster – so entgeht dir kein Schiff, das länger als ein Feld ist.`]},sudoku:{goal:`Fülle das Feld so, dass in jeder Zeile, jeder Spalte und jedem 3×3-Block jede Zahl von 1 bis 9 genau einmal steht.`,steps:[`Tippe ein leeres Feld an und dann eine Zahl.`,`Eine Zahl darf in ihrer Zeile, ihrer Spalte und ihrem Block noch nicht vorkommen.`,`Mit „Notiz“ schreibst du dir mögliche Zahlen klein in ein Feld.`],tips:[`Such zuerst Zeilen, Spalten oder Blöcke, in denen nur noch ein oder zwei Zahlen fehlen.`,`Frag auch andersherum: „Wo in diesem Block kann die 7 überhaupt noch hin?“`]},nonogramm:{goal:`Male die richtigen Felder aus – am Ende entsteht ein Pixelbild.`,steps:[`Die Zahlen neben jeder Zeile und über jeder Spalte sagen, wie lang die ausgemalten Stücke dort sind – in dieser Reihenfolge.`,`„3 1“ heißt: erst ein Stück aus drei Feldern, dann mindestens ein leeres Feld, dann ein einzelnes Feld.`,`Schalte unten von „Füllen“ auf „Kreuz“, um Felder zu markieren, die sicher leer bleiben.`,`Im Picross-Modus kosten Fehler ein Leben.`],tips:[`Fang mit großen Zahlen an: Eine 5 in einer Fünferzeile füllt alles, eine 4 lässt die drei mittleren Felder sicher sein.`,`Eine Zeile mit 0 oder ohne Zahl kannst du gleich komplett durchkreuzen.`],example:{legend:{...c(`#fde047`),"#":a(e),x:{text:`×`,color:`#64748b`}," ":{}},frames:[{grid:[` 131`,`3...`,`1...`,`1...`],note:`Oben stehen die Spalten-Zahlen (1, 3, 1), links die der Zeilen (3, 1, 1).`},{grid:[` 131`,`3###`,`1...`,`1...`],note:`Die erste Zeile ist drei Felder breit und braucht eine 3: alles ausmalen.`},{grid:[` 131`,`3###`,`1x#x`,`1x#x`],note:`Die mittlere Spalte braucht 3 – also ganz runter. Die äußeren haben ihre 1 schon: Rest durchkreuzen. Fertig ist das T.`}]}},"cross-sum":{goal:`Streiche Zahlen so weg, dass die übrigen in jeder Zeile und jeder Spalte genau die Summe am Rand ergeben.`,steps:[`Am Rand steht für jede Zeile und jede Spalte eine Zielsumme.`,`Tippe eine Zahl an, um sie zu streichen (oder zurückzuholen).`,`Jede Zahl zählt gleichzeitig für ihre Zeile UND ihre Spalte – beides muss am Ende stimmen.`],tips:[`Such Zeilen, in denen die Differenz zur Zielsumme nur von einer einzigen Zahl kommen kann.`,`Ist die Summe aller Zahlen einer Zeile schon das Ziel, bleibt dort alles stehen.`]},"lichter-aus":{goal:`Schalte alle Lampen aus.`,steps:[`Tippen schaltet das Feld um – und gleichzeitig seine vier Nachbarn (oben, unten, links, rechts).`,`An wird aus, aus wird an.`],tips:[`Die Reihenfolge der Tipps ist egal, und zweimal dasselbe Feld tippen hebt sich auf.`,`Arbeite dich Zeile für Zeile nach unten: Lösche jede Lampe mit einem Tipp auf das Feld direkt darunter.`],example:{legend:{L:a(n),o:o()},frames:[{grid:[`.L.`,`LLL`,`.L.`],note:`Fünf Lampen leuchten – wie ein Plus.`},{grid:[`.L.`,`LoL`,`.L.`],note:`Ein Tipp in die Mitte schaltet die Mitte und alle vier Nachbarn um …`},{grid:[`...`,`...`,`...`],note:`… und alles ist aus.`}]}},minensucher:{goal:`Decke alle Felder auf, unter denen keine Mine liegt.`,steps:[`Tippe ein Feld an, um es aufzudecken.`,`Eine Zahl sagt, wie viele Minen in den acht Feldern rundherum liegen. Ein leeres Feld deckt seine Nachbarn automatisch mit auf.`,`Mit dem Knopf „Fahne“ markierst du Felder, unter denen du eine Mine vermutest.`],tips:[`Eine 1 mit nur einem verdeckten Nachbarn: Dort liegt die Mine.`,`Sind um eine Zahl schon genug Fahnen gesetzt, sind alle anderen Nachbarn sicher.`],example:{legend:{...c(`#38bdf8`),"#":a(`#475569`),F:a(`#475569`,`🚩`),o:o()},frames:[{grid:[`000`,`110`,`#10`],note:`Die Einsen sagen: Genau eine Mine liegt in meinen Nachbarfeldern. Verdeckt ist nur noch das Feld unten links.`},{grid:[`000`,`110`,`F10`],note:`Also muss dort die Mine liegen → Fahne drauf, nicht antippen.`}]}},"code-knacker":{goal:`Errate den geheimen Farbcode in möglichst wenigen Versuchen.`,steps:[`Stelle eine Farbreihe zusammen und bestätige sie.`,`Für jeden Versuch gibt es kleine Stifte: Ein voller Stift = eine Farbe stimmt UND sitzt am richtigen Platz. Ein leerer Ring = die Farbe kommt vor, sitzt aber woanders.`,`Die Stifte verraten nicht, WELCHE Position gemeint ist – das musst du kombinieren.`,`Farben können im Code mehrfach vorkommen.`],tips:[`Starte mit zwei Farben doppelt (z. B. Rot-Rot-Blau-Blau): Das grenzt schnell ein, welche Farben überhaupt dabei sind.`,`Kein einziger Stift ist auch eine gute Nachricht – diese Farben sind komplett raus.`]},woertle:{goal:`Errate das gesuchte Wort mit fünf Buchstaben in sechs Versuchen.`,steps:[`Tippe ein Wort mit fünf Buchstaben ein und bestätige.`,`Grün: Buchstabe stimmt und steht am richtigen Platz.`,`Gelb: Buchstabe kommt im Wort vor, aber an anderer Stelle.`,`Grau: Buchstabe kommt gar nicht vor.`],tips:[`Beginne mit Wörtern voller häufiger Buchstaben wie E, N, R, S, T, A.`,`Ein gelber Buchstabe muss beim nächsten Versuch an einen ANDEREN Platz.`],example:{title:`Gesucht ist KATER`,legend:{l:a(`#475569`,`L`,`#e2e8f0`),s:a(`#475569`,`S`,`#e2e8f0`),t:a(n,`T`),e:a(n,`E`),A:a(r,`A`),K:a(r,`K`),T:a(r,`T`),E:a(r,`E`),R:a(r,`R`)},frames:[{grid:[`lAste`],note:`Versuch „LASTE“: Das A sitzt richtig (grün). T und E kommen vor, stehen aber falsch (gelb). L und S gibt es nicht.`},{grid:[`KATER`],note:`Also A behalten, T und E an andere Plätze, ohne L und S: „KATER“ – alles grün!`}]}},galgenmaennchen:{goal:`Errate das Wort, bevor das Männchen fertig gezeichnet ist.`,steps:[`Tippe einen Buchstaben an. Kommt er im Wort vor, wird er an allen Stellen eingetragen.`,`Jeder falsche Buchstabe zeichnet ein Stück weiter am Galgen.`],tips:[`Beginne mit E, N, I, S, R, A – das sind die häufigsten Buchstaben im Deutschen.`]},"color-flood":{goal:`Färbe das ganze Feld in einer einzigen Farbe – mit höchstens so vielen Zügen, wie erlaubt sind.`,steps:[`Du startest in einer Ecke (im Modus „Mitte“ in der Mitte). Tippe unten eine Farbe an.`,`Dein Gebiet nimmt diese Farbe an – und alle angrenzenden Felder dieser Farbe gehören ab jetzt dazu.`,`So wächst dein Gebiet Zug um Zug, bis alles geflutet ist.`],tips:[`Nimm die Farbe, die dir die meisten neuen Felder bringt – oder den Weg zu einer großen Fläche öffnet.`,`Farben, von denen nur noch wenig übrig ist, früh „aufräumen“.`],example:{legend:{r:a(`#f87171`),g:a(r),b:a(e),R:{bg:`#f87171`,ring:n},G:{bg:r,ring:n}},frames:[{grid:[`Rgg`,`rgb`,`bbb`],note:`Dein Gebiet ist das rote Feld oben links (und das rote darunter gehört schon dazu).`},{grid:[`GGG`,`GGb`,`bbb`],note:`Du wählst Grün: Dein Gebiet wird grün und schluckt alle angrenzenden grünen Felder.`},{grid:[`bbb`,`bbb`,`bbb`],note:`Dann Blau – und das ganze Feld hat eine Farbe.`}]}},"wasser-sortieren":{goal:`Sortiere die Flüssigkeiten, bis in jedem Röhrchen nur noch eine Farbe ist.`,steps:[`Tippe ein Röhrchen an (es hebt sich) und dann das Röhrchen, in das du gießen willst.`,`Gegossen wird immer die oberste Farbe – so viel davon, wie zusammenhängt und hineinpasst.`,`Gießen geht nur in ein leeres Röhrchen oder auf dieselbe Farbe.`],tips:[`Halte dir möglichst lange ein leeres Röhrchen frei – es ist dein Rangierplatz.`,`Im Modus „Versteckt“ siehst du untere Schichten erst, wenn sie oben liegen.`]},stromnetz:{goal:`Dreh die Leitungen so, dass jede Lampe mit dem Kraftwerk verbunden ist und kein Kabel ins Leere zeigt.`,steps:[`Tippe ein Feld an: Das Leitungsstück dreht sich um eine Vierteldrehung.`,`Strom fließt vom Kraftwerk (gelb, mit Blitz) durch alle verbundenen Leitungen – die leuchten dann.`,`Gelöst ist das Netz, wenn alles leuchtet und jedes Kabelende an ein anderes anschließt.`],tips:[`Fang am Rand an: Ein Kabel darf nie aus dem Feld herauszeigen (außer im Modus „Rundum“).`,`Gerade Stücke und T-Stücke am Rand haben oft nur eine mögliche Stellung.`]},eisrutsche:{goal:`Bring den Pinguin ins Iglu – in möglichst wenigen Zügen.`,steps:[`Wische in eine Richtung: Der Pinguin rutscht, bis ihn ein Rand, ein Fels, ein Eisblock oder Schnee aufhält. Anhalten mittendrin geht nicht.`,`Rutscht er gegen einen Eisblock, rutscht der Block weiter (der Pinguin bleibt davor stehen).`,`Ein Eisblock, der in ein Wasserloch fällt, füllt es auf – danach kann man darüber rutschen.`,`Das Iglu fängt den Pinguin auch im Vorbeirutschen.`],tips:[`Denk rückwärts: Von welchem Feld aus könnte er ins Iglu rutschen – und wie kommt er dorthin?`],example:{legend:{P:{text:`🐧`},I:{text:`🏠`},W:{text:`🐧`,ring:n},"#":a(`#64748b`)},frames:[{grid:[`P..#`,`....`,`....`,`..I.`],note:`Der Pinguin soll ins Iglu. Einfach nach unten wischen? Dann landet er in der Ecke unten links.`},{grid:[`..P#`,`....`,`....`,`..I.`],note:`Besser erst nach rechts: Der Fels stoppt ihn – genau über dem Iglu.`},{grid:[`...#`,`....`,`....`,`..W.`],note:`Jetzt nach unten: Er rutscht geradewegs ins Iglu. Zwei Züge!`}]}},parkchaos:{goal:`Fahr das rote Auto zur Ausfahrt.`,steps:[`Autos und Laster fahren nur vor und zurück – in der Richtung, in der sie stehen. Abbiegen geht nicht.`,`Wische ein Fahrzeug, um es zu verschieben. Es darf nichts im Weg stehen.`,`Räum so lange um, bis der Weg für das rote Auto frei ist.`],tips:[`Schau, was das rote Auto blockiert – und dann, was DIESEN Blockierer blockiert. So findest du den ersten Zug.`,`Drei Sterne gibt es nur für die kürzeste Lösung.`]},zeiger:{goal:`Schieß alle Pfeile vom Brett.`,steps:[`Tippe einen Pfeil an: Er fliegt in Richtung seiner Spitze davon – aber nur, wenn der Weg bis zum Rand frei ist.`,`Liegt ein anderer Pfeil im Weg, kostet der Versuch ein Herz. Nach drei Fehlern ist das Level verloren.`,`Finde also die richtige Reihenfolge: erst die Pfeile mit freier Bahn.`],tips:[`Schau auf die Spitze, nicht auf den geknickten Körper – nur die Flugrichtung zählt.`]},zahlenmatch:{goal:`Streiche alle Zahlen vom Feld.`,steps:[`Tippe zwei Zahlen an, die gleich sind ODER zusammen 10 ergeben (z. B. 3 und 7).`,`Die beiden müssen sich „sehen“: nebeneinander oder mit nur gestrichenen Feldern dazwischen – waagerecht, senkrecht oder schräg.`,`Es zählt auch die Lese-Reihenfolge: Das Ende einer Zeile und der Anfang der nächsten sind Nachbarn.`,`Geht nichts mehr, hängt „Hinzufügen“ alle übrigen Zahlen noch einmal unten an (nur ein paar Mal möglich).`],example:{legend:{...c(),A:{text:`3`,ring:n,color:`#fde047`},C:{text:`7`,ring:n,color:`#fde047`},x:{text:`·`,color:`#475569`}},frames:[{grid:[`3157`,`4826`],note:`Die 3 und die 7 ergeben 10 – aber dazwischen stehen noch 1 und 5.`},{grid:[`3xx7`,`4826`],note:`Sind die Zahlen dazwischen gestrichen (z. B. weil 1 und 5 andere Partner fanden) …`},{grid:[`AxxC`,`4826`],note:`… sehen sich 3 und 7 und dürfen als Paar weg.`}]}},farbfluss:{goal:`Verbinde die beiden Punkte jeder Farbe mit einer Leitung – und fülle dabei das ganze Feld.`,steps:[`Zieh mit dem Finger von einem Punkt zu seinem Partner in derselben Farbe.`,`Leitungen dürfen sich nicht kreuzen. Ziehst du durch eine andere Leitung, wird diese gekappt.`,`Fertig ist das Rätsel, wenn alle Paare verbunden sind und kein Feld leer bleibt.`],tips:[`Punkte am Rand laufen meist am Rand entlang.`,`Bleibt eine Ecke leer, muss eine Leitung einen Umweg dorthin machen.`]},2048:{goal:`Schiebe gleiche Zahlen zusammen, bis die Kachel 2048 entsteht – und danach so weit du kommst.`,steps:[`Wische nach oben, unten, links oder rechts: ALLE Kacheln rutschen in diese Richtung bis zum Anschlag.`,`Stoßen dabei zwei gleiche Zahlen zusammen, verschmelzen sie zur doppelten.`,`Nach jedem Zug erscheint eine neue kleine Kachel. Ist das Feld voll und nichts mehr verschmelzbar, ist Schluss.`],tips:[`Halte die größte Kachel in einer Ecke und wische möglichst nur in zwei, höchstens drei Richtungen.`,`Bau daneben eine absteigende Reihe (z. B. 256, 128, 64 …) – dann verschmilzt alles in einem Rutsch.`]},"connect-2248":{goal:`Verbinde Zahlen zu Ketten, lass sie verschmelzen und erreiche immer höhere Werte.`,steps:[`Zieh mit dem Finger von einer Zahl über benachbarte Felder (auch schräg).`,`Die Kette beginnt mit zwei gleichen Zahlen. Danach darf jede weitere Zahl gleich sein oder das Doppelte der vorherigen.`,`Beim Loslassen verschmilzt die Kette am letzten Feld zu einer höheren Zahl; von oben rutschen neue nach.`],tips:[`Lange Ketten bringen größere Sprünge.`,`Sammle hohe Zahlen an einer Stelle, damit sie sich später treffen.`]},subaracity:{goal:`Bau eine Stadt mit möglichst vielen Einwohnern, indem du Gebäude verschmilzt.`,steps:[`Tippe eine Gruppe aus verbundenen Gebäuden gleicher Farbe und gleicher Stufe an: Sie verschmelzen zu EINEM Gebäude der nächsten Stufe – an der Stelle, die du angetippt hast.`,`Alles darüber rutscht nach, oben kommen neue Gebäude nach.`,`Aus Gebäuden der Stufe 9 entsteht ein weißes Monument (Stufe 10). Monumente verschmelzen nur noch untereinander.`,`Der Baukran (begrenzt vorhanden) hebt ein einzelnes Gebäude um eine Stufe an. Gibt es keinen Zug und keinen Kran mehr, ist das Spiel vorbei.`],tips:[`Tippe das UNTERSTE Gebäude einer Gruppe an – dann bleibt das neue unten und versperrt nichts.`,`Halte Farben zusammen, statt sie zu durchmischen.`]},blockrausch:{goal:`Räume so viele Reihen und Spalten wie möglich ab, bevor nichts mehr aufs Feld passt.`,steps:[`Unten liegen drei Formen. Zieh sie mit dem Finger aufs Feld.`,`Eine volle Zeile oder Spalte verschwindet und gibt Punkte. Mehrere auf einmal und Serien geben Bonus.`,`Erst wenn alle drei Formen gelegt sind, kommen drei neue. Passt keine mehr, ist Schluss.`],tips:[`Lass Platz für die großen Formen (3×3-Block, lange Fünferstange).`,`Vermeide einzelne Löcher, in die nichts mehr hineinpasst.`]},sternenpost:{goal:`Schieß die Postkapsel so ab, dass sie die Raumstation trifft – am besten mit allen drei Sternen unterwegs.`,steps:[`Zieh am Startpunkt, um Richtung und Kraft einzustellen, und lass los (oder nutze die Feinjustier-Knöpfe).`,`Planeten ziehen die Kapsel an und verbiegen die Bahn. Je näher, desto stärker.`,`Später kommen dazu: Schwarze Löcher (ziehen viel stärker), Abstoßer (drücken weg), Asteroiden, Wurmlöcher (rein = am anderen Ende wieder raus) und Monde.`,`Du darfst beliebig oft neu schießen – der Schatten der letzten Bahn hilft beim Nachjustieren.`],tips:[`Ändere immer nur eine Sache: erst die Richtung ODER die Kraft.`,`Ein knapper Vorbeiflug an einem Planeten macht eine enge Kurve.`]},planetenschmiede:{goal:`Verschmilz Himmelskörper zu immer größeren – bis hin zur Sonne – ohne dass der Schacht überläuft.`,steps:[`Schiebe den Körper oben an die gewünschte Stelle und lass ihn fallen.`,`Berühren sich zwei gleiche Körper, verschmelzen sie zum nächstgrößeren.`,`Liegt etwas zu lange über der Warnlinie, ist das Spiel vorbei.`],tips:[`Sortiere nach Größe: große auf eine Seite, kleine auf die andere – dann finden Paare leichter zusammen.`,`Kleine Körper zwischen großen sind schwer wieder loszuwerden.`]},kniffel:{goal:`Hol mit fünf Würfeln die meisten Punkte, indem du alle 13 Felder des Zettels möglichst gut füllst.`,steps:[`Pro Runde darfst du bis zu dreimal würfeln. Nach jedem Wurf tippst du die Würfel an, die du behalten willst.`,`Danach MUSST du das Ergebnis in ein freies Feld eintragen – notfalls mit 0 Punkten.`,`Oben (Einser bis Sechser) zählen nur die Würfel mit dieser Zahl. Ab 63 Punkten im oberen Teil gibt es 35 Bonuspunkte.`,`Unten: Dreier-/Viererpasch (alle Augen zählen), Full House 25, kleine Straße (4 in Folge) 30, große Straße (5 in Folge) 40, Kniffel (5 gleiche) 50, Chance (alle Augen).`],tips:[`Für den Bonus brauchst du oben im Schnitt drei gleiche je Zahl.`,`Heb dir die Chance für einen verunglückten Wurf auf.`]},poker:{goal:`Gewinne Chips: mit der besten Hand am Ende – oder indem alle anderen vorher aussteigen.`,steps:[`Jeder bekommt zwei verdeckte Karten. In der Mitte kommen nach und nach fünf offene Karten für alle: erst drei (Flop), dann eine (Turn), dann noch eine (River).`,`Vor dem Flop und nach jeder neuen Karte wird gesetzt: Fold (aussteigen), Check (weitergeben, wenn nichts zu zahlen ist), Call (mitgehen), Raise (erhöhen).`,`Am Ende zählt die beste Kombination aus fünf Karten – aus deinen zwei und den fünf in der Mitte.`,`Reihenfolge von schwach nach stark: höchste Karte, ein Paar, zwei Paare, Drilling, Straße (fünf in Folge), Flush (fünf einer Farbe), Full House (Drilling + Paar), Vierling, Straight Flush.`],tips:[`Die meisten Hände wirft man vor dem Flop weg. Gut zum Mitspielen: hohe Paare, Ass mit hoher Beikarte.`,`Der Übungstisch kostet nichts – ideal zum Ausprobieren.`]},spades:{goal:`Erreiche mit deinem Partner (er sitzt dir gegenüber) zuerst die Zielpunktzahl.`,steps:[`Ansagen: Vor jeder Runde sagst du, wie viele der 13 Stiche du machen willst. Deine Ansage und die deines Partners werden zusammengezählt.`,`Stich: Jeder legt reihum eine Karte. Die Farbe der ersten Karte muss bedient werden, wenn man sie hat.`,`Den Stich gewinnt die höchste Karte der ausgespielten Farbe – außer es liegt Pik: Pik ist Trumpf und sticht alles andere.`,`Schafft euer Team mindestens die angesagten Stiche, gibt es Punkte; schafft ihr sie nicht, gibt es Minuspunkte. Auch zu viele Stiche sind schlecht: Wer über mehrere Runden zehn Stiche zu viel sammelt, bekommt einen Abzug.`,`Wer 0 ansagt („Nil“), wettet darauf, keinen einzigen Stich zu machen: +100 wenn es klappt, sonst −100.`],tips:[`Zähl für die Ansage deine Asse, Könige und langen Pik-Reihen.`,`Pik darfst du erst ausspielen, wenn schon einmal mit Pik gestochen wurde (oder du nur noch Pik hast).`]},solitaer:{goal:`Lege alle Karten nach Farben getrennt vom Ass bis zum König auf die vier Ablagen oben.`,steps:[`In den sieben Reihen legst du absteigend und abwechselnd rot/schwarz an (z. B. rote 6 auf schwarze 7).`,`Ein Tipp auf eine Karte bewegt sie automatisch an die beste erlaubte Stelle.`,`Leere Reihen dürfen nur mit einem König belegt werden. Der Stapel liefert neue Karten.`],tips:[`Deck zuerst die verdeckten Karten in den langen Reihen auf.`,`Räum eine Reihe nur leer, wenn du auch einen König dafür hast.`]},"spider-solitaer":{goal:`Baue komplette Reihen vom König bis zum Ass in einer Farbe – sie verschwinden dann vom Tisch.`,steps:[`Karten werden absteigend aneinandergelegt (Farbe egal).`,`Gemeinsam bewegen lässt sich aber nur eine Folge in EINER Farbe.`,`Der Stapel legt auf jede Reihe eine neue Karte – das geht nur, wenn keine Reihe leer ist.`],tips:[`Leg wenn möglich in derselben Farbe an – gemischte Folgen blockieren.`,`Leere Reihen sind dein wichtigstes Werkzeug zum Umsortieren.`]},"mau-mau":{goal:`Werde als Erster alle Karten los.`,steps:[`Lege eine Karte ab, die in Farbe oder Wert zur obersten Karte passt. Kannst du nicht, ziehst du eine.`,`7: Der Nächste zieht zwei Karten. 8: Der Nächste setzt aus. Ass: Richtungswechsel.`,`Bube: passt auf alles, und du darfst dir eine Farbe wünschen.`],tips:[`Heb dir einen Buben für den Schluss auf – er passt immer.`]},hexenkessel:{goal:`Hab nach acht Runden die meisten Punkte.`,steps:[`Zieh blind Zutaten aus deinem Beutel. Jede schiebt deinen Löffel weiter – das bringt Punkte und Münzen.`,`Aber: Knallerbsen heizen den Kessel auf. Wird die Hitze zu groß, explodiert er – dann gibt es in dieser Runde keine Punkte und nur halbe Münzen.`,`Du darfst jederzeit aufhören und kassieren.`,`Mit den Münzen kaufst du im Laden bessere Zutaten für deinen Beutel (bis zu zwei verschiedene pro Runde).`],tips:[`Zähl mit, wie viele Knallerbsen noch im Beutel sind – daraus ergibt sich dein Risiko.`,`Mehr gute Zutaten im Beutel heißt auch: Knallerbsen kommen seltener.`]},kartenverlies:{goal:`Kämpf dich durch zehn Etappen und besiege am Ende den Drachen.`,steps:[`Du hast pro Zug 3 Energie und eine Hand voll Karten. Jede Karte kostet Energie: Angriffe machen Schaden, Schutz blockt den nächsten Angriff, Kniffe haben Sondereffekte.`,`Über dem Gegner steht, was er als Nächstes vorhat – plane danach: Greift er stark an, lieber blocken.`,`„Zug beenden“: Der Gegner handelt, dein Schutz verfällt, du ziehst neue Karten.`,`Nach jedem Sieg wählst du eine neue Karte fürs Deck. Am Lagerfeuer kannst du heilen oder eine schwache Karte entfernen.`],tips:[`Ein kleines, gutes Deck ist stärker als ein großes: Schwache Startkarten rauswerfen lohnt sich.`,`Verwundbar = der Gegner nimmt mehr Schaden, Schwäche = er teilt weniger aus.`]},zellkrieg:{goal:`Erobere alle Zellen der Gegner.`,steps:[`In deinen Zellen wachsen von selbst Einheiten nach (große Zellen fassen mehr, wachsen aber langsamer).`,`Wische von einer eigenen Zelle zu einem Ziel: Ein Teil der Einheiten schwärmt los. Wischst du über mehrere eigene Zellen, schicken alle gemeinsam.`,`Kommen mehr Einheiten an, als in der Zielzelle sitzen, gehört sie dir. Bei eigenen Zellen verstärkst du einfach.`,`Sonderzellen: Türme schießen auf fremde Schwärme, Turbo-Zellen schicken schneller, Schild-Zellen halten doppelt so viel aus, Brut-Zellen wachsen doppelt so schnell.`,`Feldzug: 120 Level in 8 Akten. Tippe oben links auf „Level …“, um jedes freigeschaltete Level zu wählen und Sterne nachzuholen.`,`Ab Level 46 kommen neue Regeln dazu: Membran-Wände (nur mit freier Sicht senden), treibende Zellen, Säure (frisst Einheiten) und Schleim (bremst), Kerne (fällt der Kern, ist der ganze Stamm besiegt), Quellen (alle deine Zellen wachsen 30 % schneller) und Sonderaufträge wie „Überleben“ oder „Gegen die Uhr“.`],tips:[`Neutrale (graue) Zellen zuerst – sie wehren sich nicht.`,`Greif mit mehreren Zellen gleichzeitig an, statt nacheinander.`,`Lass nie eine Zelle an der Front leer zurück.`,`Bei Kernen lohnt der direkte Angriff: Wer den gegnerischen Kern nimmt, löscht den ganzen Stamm aus.`,`Säure lieber umfliegen – ein Umweg kostet Zeit, aber keine Einheiten.`]},turmwacht:{goal:`Lass keine Gegner bis zu deiner Burg durch.`,steps:[`Tippe auf einen Bauplatz neben dem Weg und wähle einen Turm. Türme kosten Gold.`,`Besiegte Gegner geben Gold. Damit baust du neue Türme oder verbesserst vorhandene (antippen).`,`Jeder Gegner, der die Burg erreicht, kostet Leben. Ohne Leben ist Schluss.`],tips:[`Kurven sind die besten Plätze: Dort bleiben Gegner lange in Reichweite.`,`Lieber wenige ausgebaute Türme als viele schwache.`]},"darts-master":{goal:`Bring deinen Punktestand von 301 oder 501 auf exakt 0.`,steps:[`Jede Runde hast du drei Pfeile. Die getroffenen Punkte werden abgezogen.`,`Der schmale äußere Ring zählt doppelt, der schmale innere dreifach. Die Mitte (Bullseye) zählt 50, der Ring darum 25.`,`Wirfst du mehr, als du noch brauchst, zählt die ganze Runde nicht („Bust“).`,`Mit „Double-Out“ muss der letzte Pfeil ein Doppelfeld sein.`],tips:[`Das höchste Feld ist die Dreifach-20 (60 Punkte) – nicht die Mitte.`]},billiards:{goal:`8-Ball: Versenke alle Kugeln deiner Gruppe (Volle oder Halbe) und danach die schwarze 8.`,steps:[`Ziele per Wisch, stelle rechts die Kraft ein und stoße.`,`Die erste versenkte Kugel entscheidet, wer die Vollen und wer die Halben hat.`,`Versenkst du eine eigene Kugel, bleibst du am Tisch.`,`Foul (Weiße versenkt, nichts getroffen oder zuerst eine fremde Kugel getroffen): Der Gegner ist dran.`,`Wer die 8 zu früh oder mit einem Foul versenkt, verliert sofort.`],tips:[`Denk einen Stoß weiter: Wo bleibt die Weiße liegen?`,`Sanfte Stöße sind genauer als harte.`]},"cup-toss":{goal:`Triff alle Becher des Gegners, bevor er deine trifft.`,steps:[`Wische nach oben, um den Ball zu werfen. Richtung und Länge des Wischs bestimmen, wohin er fliegt.`,`Jeder getroffene Becher verschwindet.`,`Einmal pro Spiel darfst du die restlichen Becher des Gegners enger zusammenstellen lassen.`],tips:[`Wirf lieber etwas zu weit als zu kurz – hinten stehen meist noch Becher.`]},panzer:{goal:`Zerstöre den Panzer des Gegners.`,steps:[`Zieh am Bildschirm, um Winkel und Kraft einzustellen – der Bogen zeigt die Flugbahn ungefähr. Dann FEUER.`,`Der Wind (Anzeige oben) drückt das Geschoss zur Seite – gleich das beim Zielen aus.`,`Treffer reißen Krater ins Gelände. Mit begrenztem Sprit kannst du deinen Panzer verschieben.`,`Sonderwaffen sind stärker, aber nur zweimal vorhanden.`],tips:[`Merk dir deinen letzten Schuss und korrigiere in kleinen Schritten.`]},spion:{goal:`Alle zusammen: den Spion enttarnen. Als Spion: nicht auffliegen – oder den Ort erraten.`,steps:[`Das Handy geht reihum. Jeder sieht geheim seine Karte: Alle bekommen denselben Ort – nur der Spion nicht.`,`Dann fragt ihr euch reihum gegenseitig Dinge über den Ort („Ist es dort eher laut?“). Wer geantwortet hat, stellt die nächste Frage.`,`Fragen und Antworten sollten zeigen, dass man den Ort kennt – ohne ihn dem Spion zu verraten.`,`Am Ende (oder wenn jemand einen Verdacht hat) stimmt ihr ab, wer der Spion ist.`],tips:[`Zu genaue Fragen helfen dem Spion, zu vage machen dich selbst verdächtig.`]},"verbotene-woerter":{goal:`Dein Team soll in der Zeit so viele Begriffe wie möglich erraten.`,steps:[`Du erklärst den Begriff oben – darfst dabei aber weder ihn noch die vier verbotenen Wörter darunter sagen.`,`Errät dein Team den Begriff: „Richtig“ tippen, es kommt der nächste.`,`Rutscht dir ein verbotenes Wort heraus, gibt es einen Minuspunkt. Das andere Team passt auf.`],tips:[`Auch Teile des Worts, Übersetzungen und Gesten sind tabu.`]},"reflex-duell":{goal:`Gewinne mehr Mini-Runden als dein Gegenüber.`,steps:[`Legt das Handy flach zwischen euch: Jeder bekommt eine Hälfte des Bildschirms.`,`Vor jeder Runde steht kurz da, worum es geht – z. B. „Tippe, wenn es grün wird“ oder „Tippe die größere Zahl“.`,`Wer richtig und schneller ist, bekommt den Punkt. Wer zu früh oder falsch tippt, schenkt ihn dem anderen.`],tips:[`Lies die Ansage – bei „Farbfalle“ und „Stimmt das?“ verliert, wer nur auf Tempo spielt.`]},seilschwinger:{goal:`Schwing so weit wie möglich durch den Dschungel.`,steps:[`Finger auf den Bildschirm = der Affe greift die nächste Liane. Loslassen = er fliegt.`,`Lass im Aufschwung los, wenn es schräg nach vorn oben geht – dann fliegst du am weitesten.`,`Ein perfekter Absprung gibt Extra-Tempo und erhöht die Kombo: Bananen zählen dann mehrfach.`,`Dornen, Sumpf und Papageien sind tabu. Morsche Äste brechen nach kurzer Zeit.`],tips:[`Halte den Finger schon in der Luft gedrückt – die Liane greift, sobald eine in Reichweite ist.`]}};export{S as GUIDES};